INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q5851623', 'Revolt of the Comuneros', 'The Revolt of the Comuneros (Spanish: Revolución Comunera) was a series of uprisings by settlers in Paraguay in the Viceroyalty of Peru against the Spanish authorities from 1721 to 1725 and 1730–1735. The underlying cause of the unrest was strong anti-Jesuit feelings among the Paraguayans and dislike for any governor seen as favoring the Jesuits.', 1721, NULL, NULL, 1735, NULL, NULL, 'year', '1721–1735', 41, 'https://en.wikipedia.org/wiki/Revolt_of_the_Comuneros_(Paraguay)'),
  ('Q5915169', 'Independence of Paraguay', 'The Independence of Paraguay de facto started on 14 May 1811 after the Revolution of May 14 when a local ruling junta was created. In early 1811 Paraguayan forces had repeatedly defeated the Argentine army which considered Paraguay to be a break-away province.', 1811, NULL, NULL, 1814, NULL, NULL, 'year', '1811–1814', 30, 'https://en.wikipedia.org/wiki/Independence_of_Paraguay'),
  ('Q58947', 'Paraguayan War', 'The Paraguayan War, also known as the War of the Triple Alliance, was a war in South America that lasted from 1864 to 1870. It was fought between Paraguay and the Triple Alliance of Argentina, Brazil and Uruguay.', 1864, 10, 12, 1870, 3, 1, 'day', '12 October 1864 – 1 March 1870', 78, 'https://en.wikipedia.org/wiki/Paraguayan_War'),
  ('Q2236812', 'Battle of Riachuelo', 'The Battle of Riachuelo (or Battle of the Riachuelo) was a large and decisive naval battle of the Paraguayan War between Paraguay and the Empire of Brazil. By late 1864, Paraguay had scored a series of victories in the war, but on 11 June 1865, its naval defeat by the Brazilians on the Paraná River began to turn the tide in favor of the allies.', 1865, 6, 11, NULL, NULL, NULL, 'day', '11 June 1865', 52, 'https://en.wikipedia.org/wiki/Battle_of_Riachuelo'),
  ('Q6065909', 'Battle of Paso de Mercedes', 'The Battle of Paso de Mercedes was fought on 11 August 1865 during the Paraguayan invasion of the Argentine province of Corrientes. The battle took place at Bella Vista along the Paraná River, west of Mercedes.', 1865, 7, 18, NULL, NULL, NULL, 'day', '18 July 1865', 34, 'https://en.wikipedia.org/wiki/Battle_of_Paso_de_Mercedes'),
  ('Q2305019', 'Battle of Curupaity', 'The Battle of Curupayty was a key battle in the Paraguayan War. On the morning on 22 September 1866, the joint force of Brazilian, Argentine, and Uruguayan armies attacked Paraguayan fortified trenches on Curupayty.', 1866, 9, 22, NULL, NULL, NULL, 'day', '22 September 1866', 52, 'https://en.wikipedia.org/wiki/Battle_of_Curupayty'),
  ('Q3289878', 'Battle of Curuzú', 'The Battle of Curuzú occurred between September 1 and 3, 1866 during the Paraguayan War. After the first Battle of Tuyutí, won by the Allies on 24 May 1866, an Allied council of war decided to use their navy to bombard and capture the Paraguayan battery at Curupayty.', 1866, NULL, NULL, 1866, 9, 3, 'year', '1866', 41, 'https://en.wikipedia.org/wiki/Battle_of_Curuz%C3%BA'),
  ('Q3646790', 'Battle of Estero Bellaco', 'The Battle of Estero Bellaco was one of the bloodiest battles of the Paraguayan War. The battle was fought on 2 May 1866 with the Paraguayan Army suffering 2,000 casualties among the dead and wounded.', 1866, 5, 2, NULL, NULL, NULL, 'day', '2 May 1866', 45, 'https://en.wikipedia.org/wiki/Battle_of_Estero_Bellaco'),
  ('Q16489568', 'Battle of Boquerón', 'The Battle of Boquerón was fought on 16 July 1866 and the Battle of Sauce on 18 July 1866, between an allied force of Uruguayans, Brazilians, and Argentines on one side and Paraguay on the other in the Paraguayan War. The Spanish-born Uruguayan officer León de Pallejas (1816–1866) and the Paraguayan officer Elizardo Aquino were killed in the battle.', 1866, 7, 16, 1866, 7, 18, 'day', '16 July 1866 – 18 July 1866', 37, 'https://en.wikipedia.org/wiki/Battle_of_Boquer%C3%B3n_(1866)'),
  ('Q5723098', 'Second Battle of Tuyutí', 'The Second Battle of Tuyutí was fought on 3 November 1867 between the Paraguayan Army and a smaller allied Brazilian-Argentine force. The Paraguayans lost twice as many soldiers as the allies and were defeated.', 1867, 11, 3, NULL, NULL, NULL, 'day', '3 November 1867', 34, 'https://en.wikipedia.org/wiki/Second_Battle_of_Tuyut%C3%AD'),
  ('Q6065903', 'Siege of Curupaiti', 'The passage of Curupayty was an allied naval operation carried out on 15 August 1867, in the context of the Paraguayan War, which aimed to force the passage of Brazilian battleships against the defensive fortifications installed in the Curupayty fort on the banks of the Paraguay river. There was a second crossing on 13 February 1868 with a fleet of armored monitors destined to join the fleet that had crossed first to form the squadron responsible for forcing the Passage of Humaitá.', 1867, 8, 15, NULL, NULL, NULL, 'day', '15 August 1867', 34, 'https://en.wikipedia.org/wiki/Passage_of_Curupayty_(1867)'),
  ('Q3647744', 'Battle of Avay', 'The Battle of Avay of 11 December 1868 was one of the last major combat engagements of the Paraguayan War, fought near the Avay stream in Paraguayan territory between the forces the Triple Alliance and the Paraguayan Army.', 1868, 12, 11, NULL, NULL, NULL, 'day', '11 December 1868', 39, 'https://en.wikipedia.org/wiki/Battle_of_Avay'),
  ('Q5722546', 'Battle of Lomas Valentinas', 'The Battle of Lomas Valentinas (also known as the Battle of Itá Ybaté) was fought in the Central Department of Paraguay on December 21–27, 1868. The Paraguayan Army, led personally by president Francisco Solano López, was decisively defeated, though López managed to escape.', 1868, NULL, NULL, 1868, 12, 27, 'year', '1868', 41, 'https://en.wikipedia.org/wiki/Battle_of_Lomas_Valentinas'),
  ('Q5778559', 'Battle of Acayuazá', 'The Battle of Acayuazá was fought on July 18, 1868, on the outskirts of Reduto-Corá between the allied troops of the Triple Alliance and the Paraguayan army. Despite being outnumbered, the Paraguayan troops prevailed over the allies.', 1868, 7, 18, NULL, NULL, NULL, 'day', '18 July 1868', 34, 'https://en.wikipedia.org/wiki/Battle_of_Acayuaz%C3%A1'),
  ('Q7510095', 'Passage of Humaitá', 'The Passage of Humaitá (Portuguese: Passagem de Humaitá) was an operation of riverine warfare during the Paraguayan War − the most lethal in South American history − in which a force of six Imperial Brazilian Navy armoured vessels was ordered to dash past under the guns of the Paraguayan fortress of Humaitá. Some competent neutral observers had considered that the feat was very nearly impossible.', 1868, 2, 19, NULL, NULL, NULL, 'day', '19 February 1868', 39, 'https://en.wikipedia.org/wiki/Passage_of_Humait%C3%A1'),
  ('Q15048733', 'Assault on the battleships Cabral and Lima Barros', 'The assault on the battleships Cabral and Lima Barros was a naval action that took place at dawn on 2 March 1868, during the Paraguayan War, when Paraguayan canoes, yoked two by two, disguised with branches and with 50 soldiers each, approached the Brazilian ironclads Lima Barros and Cabral.', 1868, 3, 2, NULL, NULL, NULL, 'day', '2 March 1868', 34, 'https://en.wikipedia.org/wiki/Assault_on_the_battleships_Cabral_and_Lima_Barros'),
  ('Q65170649', '1868 San Fernando massacre', 'The San Fernando massacre (Spanish: Matanza de San Fernando) was an episode that took place on 21 December 1868, on the eve of the Battle of Lomas Valentinas, during the Pikysyry campaign in the Paraguayan War, which consisted of the summary trial and execution of hundreds of prisoners by order of Paraguayan president Francisco Solano López. Some prisoners were accused of plotting an alleged conspiracy to overthrow López.', 1868, 12, 21, NULL, NULL, NULL, 'day', '21 December 1868', 34, 'https://en.wikipedia.org/wiki/1868_San_Fernando_massacre'),
  ('Q2717440', 'Victoria de paraguay', 'The Battle of Acosta Ñu (Guarani: Acosta Ñu ñorairõ), also known as the Children''s Battle (Spanish: Batalla de los Niños) in Paraguay and the Battle of Campo Grande (Portuguese: Batalha de Campo Grande) in Brazil, took place on 16 August 1869. It was the last major engagement of the Paraguayan War between the Triple Alliance and Paraguay.', 1869, 8, 16, NULL, NULL, NULL, 'day', '16 August 1869', 50, 'https://en.wikipedia.org/wiki/Battle_of_Acosta_%C3%91u'),
  ('Q3504617', 'Battle of Cerro Corá', 'The Battle of Cerro Corá (Spanish pronunciation: [ˈsero koˈɾa]) was the last major battle of the Paraguayan War, fought on 1 March 1870, in the vicinity of Cerro Corá, 454 kilometres (280 mi) northeast of Paraguay''s capital Asunción. It is known for being the battle in which Francisco Solano López, Paraguayan president, was killed at the hands of the Imperial Brazilian Army.', 1870, 3, 1, NULL, NULL, NULL, 'day', '1 March 1870', 48, 'https://en.wikipedia.org/wiki/Battle_of_Cerro_Cor%C3%A1'),
  ('Q65077988', '1911 Paraguayan Civil War', 'The Paraguayan Civil War was a civil war fought in Paraguay from 15 July 1911 to 11 May 1912. It started when members of the Liberal Party, led by Eduardo Schaerer and former president Manuel Gondra revolted against the rule of Liberato Marcial Rojas, and against major Albino Jara.', 1911, 7, 15, 1912, 5, 11, 'day', '15 July 1911 – 11 May 1912', 26, 'https://en.wikipedia.org/wiki/Paraguayan_Civil_War_(1911%E2%80%931912)'),
  ('Q4147509', 'Paraguayan Civil War of 1922–1923', 'The Paraguayan Civil War (1922), took place between 27 May 1922 and 10 July 1923, within the borders of Paraguay. It started when supporters of colonel Adolfo Chirife attempted to forcefully restore the implementation of presidential elections canceled by President Eusebio Ayala.', 1923, 7, 10, 1923, 7, 10, 'day', '10 July 1923', 45, 'https://en.wikipedia.org/wiki/Paraguayan_Civil_War_(1922%E2%80%931923)'),
  ('Q223126', 'Chaco War', 'The Chaco War (Spanish: Guerra del Chaco, Guarani: Cháko Ñorairõ) was fought from 1932 to 1935. It was between Bolivia and Paraguay over control of the northern part of the Gran Chaco region (known in Spanish as the Chaco Boreal), which was thought to be rich in petroleum.', 1932, 9, 9, 1935, 6, 12, 'day', '9 September 1932 – 12 June 1935', 74, 'https://en.wikipedia.org/wiki/Chaco_War'),
  ('Q1122487', 'Battle of Boquerón', 'The Battle of Boquerón was fought September 9–29, 1932, between the Bolivian and Paraguayan armies in and around the stronghold of Boquerón. It was the first major battle of the Chaco War.', 1932, NULL, NULL, 1932, 9, 29, 'year', '1932', 39, 'https://en.wikipedia.org/wiki/Battle_of_Boquer%C3%B3n_(1932)'),
  ('Q25340151', 'February Revolution', 'The February Revolution in Paraguay was a military coup d''état on February 17, 1936, that ousted President Eusebio Ayala and brought to power colonel Rafael Franco. The revolution marked the end of Liberal Party rule in Paraguay and started the ascendancy of military dictatorships that lasted for more than half a century.', 1936, 2, 17, NULL, NULL, NULL, 'day', '17 February 1936', 39, 'https://en.wikipedia.org/wiki/February_Revolution_(Paraguay)'),
  ('Q1122422', 'Paraguayan Civil War of 1947', 'The Paraguayan Civil War (also known as the Barefoot Revolution and the Third Paraguayan Civil War) was a civil war in Paraguay that lasted from 7 March to 20 August 1947.', 1947, NULL, NULL, 1947, 8, 20, 'year', '1947', 52, 'https://en.wikipedia.org/wiki/Paraguayan_Civil_War_(1947)'),
  ('Q30586190', '1954 Paraguayan coup d''etat', 'The 1954 Paraguayan coup d''état occurred in May 1954. It was led by Alfredo Stroessner, with the support of Epifanio Méndez Fleitas, and resulted in the overthrow of the government of Federico Chávez.', 1954, 5, NULL, 1954, 5, 7, 'month', 'May 1954 – 7 May 1954', 39, 'https://en.wikipedia.org/wiki/1954_Paraguayan_coup_d''%C3%A9tat'),
  ('Q16257445', 'Genocide of indigenous peoples in Paraguay', 'There are 17 indigenous tribes in Paraguay with the majority having their territories in the Chaco region. Tribes in this region include the Guaraní, Ayoreo, Toba-Maskoy, Aché and Sanapan which according to the census from 2002 number an estimated 86,000 or roughly around 2 per cent of the total population.', 1956, NULL, NULL, 1989, NULL, NULL, 'year', '1956–1989', 30, 'https://en.wikipedia.org/wiki/Genocide_of_Indigenous_peoples_in_Paraguay'),
  ('Q19601700', '1989 Paraguayan coup d''etat', 'The 1989 Paraguayan coup d''état, also known as La Noche de la Candelaria, was a coup d''état that took place on 2–3 February 1989 in Asunción, Paraguay, led by General Andrés Rodríguez against the regime of long-time leader Alfredo Stroessner. The bloody overthrow which saw numerous soldiers killed in street fighting was sparked by a power struggle in the highest echelons of the government.', 1989, 2, 3, 1989, 2, 3, 'day', '3 February 1989', 43, 'https://en.wikipedia.org/wiki/1989_Paraguayan_coup_d''%C3%A9tat'),
  ('Q16962642', 'insurgency in Paraguay', 'The insurgency in Paraguay, also known as the Paraguayan People''s Army insurgency and the EPP rebellion (from the group''s name in Spanish: Ejército del Pueblo Paraguayo), is an ongoing low-level armed conflict in northeastern Paraguay. Between 2005 and the summer of 2014, the EPP campaign resulted in at least 145 deaths, the majority of them local ranchers, private security guards, and police officers, along with several insurgents.', 2005, 8, 27, NULL, NULL, NULL, 'day', '27 August 2005', 41, 'https://en.wikipedia.org/wiki/Insurgency_in_Paraguay'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');
